import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.DgVVaeR-.js";const p=JSON.parse('{"title":"設定とプライバシー","description":"Palleriaの表示、通信、バックアップ、プライバシー設定。","frontmatter":{"title":"設定とプライバシー","description":"Palleriaの表示、通信、バックアップ、プライバシー設定。"},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1791090709000}'),r={name:"guide/settings.md"};function o(n,a,s,d,h,c){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="設定とプライバシー" tabindex="-1">設定とプライバシー <a class="header-anchor" href="#設定とプライバシー" aria-label="Permalink to &quot;設定とプライバシー&quot;">​</a></h1><h2 id="表示とテーマ" tabindex="-1">表示とテーマ <a class="header-anchor" href="#表示とテーマ" aria-label="Permalink to &quot;表示とテーマ&quot;">​</a></h2><p>アプリの外観と画像表示を好みに合わせて調整できます。</p><ul><li>ライト・ダークテーマ</li><li>AMOLED向けの黒基調テーマ</li><li>表示言語</li><li>画像品質</li><li>一覧や閲覧画面の表示設定</li></ul><p>高画質を選ぶと通信量と保存容量が増えることがあります。モバイル回線ではデータ使用量に注意してください。</p><h2 id="feature-flag" tabindex="-1">Feature Flag <a class="header-anchor" href="#feature-flag" aria-label="Permalink to &quot;Feature Flag&quot;">​</a></h2><p>設定のFeature Flagから、次の表示機能を個別に有効化できます。初期状態では無効です。</p><ul><li><strong>トップスクロールのぼかし効果</strong>: ホーム、ランキング、ブックマーク、検索トップ、プロフィールで、スクロール中のヘッダー背景をぼかします。文字とボタンは鮮明に表示します。Android 12未満では半透明背景を使用します。</li><li><strong>ナビゲーションバーをアイコンのみにする</strong>: 標準の下部ナビゲーションのラベルを非表示にします。読み上げ用の名前は保持します。フローティングナビゲーションは元からアイコンのみです。</li><li><strong>高速スクロール時の描画軽量化</strong>: 高速スクロール中はヘッダーのぼかし、プレビューの影、一覧の配置アニメーションと読み込み時のシマーを抑制します。スクロールが落ち着くと元に戻ります。</li><li><strong>コマンドパレット</strong>: ログイン後に<code>Ctrl + K</code>で開きます。検索語を入力するか、ホーム・ランキング・ブックマーク・小説・設定への移動、テーマ変更を選択できます。上下キーで選択、Enterで実行、Escで閉じます。ロック中は使用できません。</li></ul><p>グリッドのピンチによる列数変更では、作品と小説カードの配置・高さをアニメーションさせます。描画軽量化フラグが有効で、高速スクロールしている間は省略します。</p><p>3ボタンナビゲーションの領域は、縦画面の下端・横画面の側面ともアプリの表示領域から確保します。</p><h2 id="通信" tabindex="-1">通信 <a class="header-anchor" href="#通信" aria-label="Permalink to &quot;通信&quot;">​</a></h2><p>環境に応じてPixiv画像プロキシなどのネットワーク設定を変更できます。接続先を変更する場合は、信頼できるサービスかを確認してください。</p><h2 id="ミュート" tabindex="-1">ミュート <a class="header-anchor" href="#ミュート" aria-label="Permalink to &quot;ミュート&quot;">​</a></h2><p>見たくないユーザー、タグ、作品をミュートできます。ミュート条件は設定から確認・解除できます。</p><h2 id="バックアップと復元" tabindex="-1">バックアップと復元 <a class="header-anchor" href="#バックアップと復元" aria-label="Permalink to &quot;バックアップと復元&quot;">​</a></h2><p>対応する設定やデータをJSONへ書き出し、あとで復元できます。</p><div class="warning custom-block"><p class="custom-block-title">バックアップの取り扱い</p><p>バックアップには利用状況や設定が含まれる可能性があります。共有ストレージやクラウドへ保存する場合は、公開範囲を確認してください。</p></div><h2 id="セキュリティ" tabindex="-1">セキュリティ <a class="header-anchor" href="#セキュリティ" aria-label="Permalink to &quot;セキュリティ&quot;">​</a></h2><ul><li>PINロック</li><li>生体認証</li><li>セキュアウィンドウ</li><li>スクリーンショット保護</li><li>アプリアイコンの切り替え</li></ul><p>生体認証の利用可否は、端末のハードウェアとAndroid設定に依存します。PINを忘れないよう、安全な方法で管理してください。</p><h2 id="データを守るために" tabindex="-1">データを守るために <a class="header-anchor" href="#データを守るために" aria-label="Permalink to &quot;データを守るために&quot;">​</a></h2><ol><li>APKは案内している公式配布元から取得する</li><li>リフレッシュトークンを他人へ渡さない</li><li>端末の画面ロックを有効にする</li><li>OSとPalleriaを最新の状態に保つ</li><li>不要になったバックアップを安全に削除する</li></ol>',22)])])}const g=l(r,[["render",o]]);export{p as __pageData,g as default};
